using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ── CalculateTotal: DataRow-driven tests ──────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Multiple items, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero price yields zero total")]
    [DataRow(99.99, 0, 0.20, 0.00,   DisplayName = "Zero quantity yields zero total")]
    [DataRow(10.00, 1, 1.0,  20.00,  DisplayName = "100% tax doubles the price")]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "0% tax leaves price unchanged")]
    public void CalculateTotal_ReturnsExpectedAmount(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    // ── CalculateTotal: DynamicData-driven edge-case tests ────────────

    public static IEnumerable<object[]> InvalidInputCases
    {
        get
        {
            yield return new object[] { -1m,  1,  0.1m, "unitPrice",      "Negative unit price" };
            yield return new object[] { 10m, -1,  0.1m, "quantity",       "Negative quantity" };
            yield return new object[] { 10m,  1, -0.1m, "taxRate",        "Negative tax rate" };
            yield return new object[] { 10m,  1,  1.5m, "taxRate",        "Tax rate above 1" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidInputCases), DynamicDataSourceType.Property,
        DynamicDataDisplayName = nameof(GetInvalidInputDisplayName))]
    public void CalculateTotal_InvalidInput_ThrowsArgumentOutOfRange(
        decimal unitPrice, int quantity, decimal taxRate,
        string expectedParamName, string _)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(unitPrice, quantity, taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    public static string GetInvalidInputDisplayName(MethodInfo _, object[] data) => (string)data[4];

    // ── ApplyDiscount: DataRow-driven tests ───────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0,   100.00, DisplayName = "0% discount — full price")]
    [DataRow(100.00, 10.0,  90.00,  DisplayName = "10% discount")]
    [DataRow(100.00, 50.0,  50.00,  DisplayName = "50% discount — half price")]
    [DataRow(100.00, 100.0, 0.00,   DisplayName = "100% discount — free")]
    [DataRow(49.99,  25.0,  37.4925,DisplayName = "Fractional result")]
    public void ApplyDiscount_ReturnsExpectedPrice(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ── ApplyDiscount: DynamicData-driven boundary tests ──────────────

    public static IEnumerable<object[]> InvalidDiscountCases
    {
        get
        {
            yield return new object[] { 100m, -1m,   "Negative discount" };
            yield return new object[] { 100m, 100.1m,"Discount above 100%" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Property,
        DynamicDataDisplayName = nameof(GetDiscountDisplayName))]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRange(
        decimal price, decimal discountPercent, string _)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    public static string GetDiscountDisplayName(MethodInfo _, object[] data) => (string)data[2];
}

